"""Glossary: every technical term and abbreviation on the site, explained simply."""

GLOSSARY = {
    'Stock market': [
        ('Share', 'a small piece of the company. Whoever owns shares owns part of the company and gains if the company grows.'),
        ('Closing price', 'the last price of the day, when the US market closes (23:00, Romanian time). All prices on the site are closing prices, not real time.'),
        ('Market cap', "what all the company's shares would cost at today's price: price × number of shares. E.g. $345M."),
        ('M $ / B $', 'millions / billions of dollars. $1B = $1.000M.'),
        ('Volume', 'how many shares were bought and sold in a day.'),
        ('Liquidity (daily traded value)', "how much money trades in the company's shares per day. High = you can buy or sell easily without moving the price."),
        ('Return', 'how much a stock gained (+) or lost (−) over a period, in percent.'),
        ('IPO', 'Initial Public Offering: the first stock market listing, when the company sells shares to the public for the first time.'),
        ('SPAC', 'an "empty" listed company created only to buy a private company; this is how the private company gets listed without a classic IPO. Historically, many SPACs did poorly.'),
        ('Direct listing', 'the company lists without selling new shares; only existing shares trade.'),
        ('Delisting', 'the stock is removed from the exchange (usually a price too low or serious problems).'),
        ('Split / reverse split', 'splitting shares into more (split) or merging them into fewer (reverse split, e.g. 10 old = 1 new). A reverse split is often a sign the price fell below $1.'),
        ('ADS', 'American Depositary Share: a certificate through which a foreign company trades in the US; one ADS can represent several shares.'),
        ('Lock-up', 'the period (usually 6 months after the IPO) during which founders and early investors may not sell. When it expires, the price often drops.'),
        ('Insider', "a person from the company's management (executive, board member) or a very large shareholder. When they buy with their own money, it's a sign of confidence."),
        ('Index', 'a "basket" of stocks that shows how the market is doing overall.'),
        ('Russell 2000 · IWM', 'the index of 2,000 small US companies; IWM is the fund that tracks it.'),
        ('S&P 500 · SPY', 'the index of 500 large US companies; SPY is the fund that tracks it.'),
        ('ETF / fund', 'a fund traded like a stock that holds many stocks at once.'),
        ('Small cap', 'a small listed company (here: between $50M and $2B).'),
    ],
    'Official filings (SEC)': [
        ('SEC', 'Securities and Exchange Commission: the US authority that oversees the stock market. Listed companies must file reports with it.'),
        ('EDGAR', "the SEC's free public archive of all company filings. Our data comes from here."),
        ('10-K / 10-Q', 'the annual report (10-K) and the quarterly report (10-Q) of a US company.'),
        ('20-F / 6-K', 'the annual report (20-F) and press releases (6-K) of foreign companies listed in the US.'),
        ('8-K', 'an official release about an important event (contract, resignation, auditor change, exchange problems). The number after it (e.g. 8-K 3.01) tells the type of event.'),
        ('S-1 / prospect', 'the IPO presentation document: the business, the risks, the numbers.'),
        ('S-3 / 424B', 'filings in which the company announces it is issuing new shares (usually to raise money).'),
        ('Form 3 / Form 4', 'insider filings: Form 3 = the shares they own when they take office, Form 4 = every purchase or sale (within 2 business days).'),
        ('13F', 'the quarterly report of big funds (over $100M) listing the shares they hold. It comes out up to 45 days late.'),
        ('13D / 13G', 'the filing of someone who now owns over 5% of the company.'),
        ('DEF 14A', "the document for the shareholders' meeting; we take management biographies from it."),
        ('XBRL', 'the digital format in which companies file their financial numbers; this is how we can read them automatically.'),
        ('Going concern', 'the warning (in the report) that the company may not survive the next 12 months. A serious alarm.'),
        ('Auditor', 'an independent firm that checks the reported numbers. Changing it can be a sign of trouble.'),
    ],
    'Financials': [
        ('Revenue (12 months)', 'all money collected from sales over the last 12 months (revenue, TTM).'),
        ('Revenue growth', 'how much revenue grew versus a year ago, in percent.'),
        ('Growth per year (CAGR)', 'the average yearly growth over several years; smooths out very good and very bad years.'),
        ('Gross margin', 'how much is left from every $100 of sales after the direct cost of the product. 60% = $60 left. High = good business.'),
        ('Cash flow (operating)', 'how much cash actually comes in (+) or goes out (−) from the business in a year.'),
        ('Net income', 'what is left after all expenses and taxes. Negative = loss.'),
        ('Cash', 'the cash the company has in the bank.'),
        ('Cash runway (cash for N months)', 'how many months its cash would last if it keeps losing money at the current rate.'),
        ('Self-funding', "the company brings in more cash than it spends; it doesn't need new money."),
        ('Dilution', 'the company issues new shares; each old share represents a smaller part of the company.'),
        ('P/E', 'price / earnings: how many times one year\'s profit the company costs. "loss" = the company has no profit, so P/E can\'t be calculated.'),
        ('P/S', "price / sales: the company's market value divided by one year's revenue."),
        ('EV / EV/S', "EV = the company's market value minus its cash. EV/S = EV divided by one year's revenue."),
    ],
    'Charts': [
        ('Candles', 'each candle = one day: the body shows the open and close, the thin wick the high and low. Green = up, red = down.'),
        ('Line', 'the simple chart, with closing prices only.'),
        ('MA20 / MA50', 'the average price over the last 20 / 50 days; shows the trend and smooths out the noise.'),
        ('D / High / Low / I', 'the open, high, low and close of the day selected on the chart.'),
        ('Vol', "the day's volume (shares traded). K = thousands, M = millions."),
        ('1M / 3M / 6M / 1Y / All', 'the chart period: 1 month, 3 months, 6 months, 1 year, full history.'),
        ('52-week range', 'the lowest and highest price of the last year.'),
    ],
    'SKYNODE': [
        ('Financial health', 'our plain summary of a company\'s latest filed numbers: Solid (healthy on almost all checks), Mixed (some healthy, some not) or Fragile (little cash or revenue, or warning signs). It describes the company, not its shares - see "How it works".'),
        ('Alarms', 'serious warning signs from official filings: bankruptcy risk, delisting warning, restated reports, many new shares issued.'),
        ('The universe', 'all AI companies listed in the US over the last 3 years (including delisted ones).'),
        ('Tracked', 'a company that passed the size filter ($50M - $2B) and the liquidity filter (at least $500.000 a day).'),
        ('Watchlist', 'a personal list of companies to follow (full version).'),
        ('Brief', 'a short daily summary of new filings (full version).'),
        ('Backtest (historical test)', 'checking how a method would have worked in the past, using only the data available at each moment.'),
        ('Survivorship bias', 'the mistake of studying only the companies that survived; results would look better than they are. We keep delisted companies too.'),
        ('Median', "the middle value: half the cases are above, half below. Unlike the average, it isn't fooled by a few extreme cases."),
        ('Correlation', 'how well two things move together, from −1 to +1. Above 0 = the better-rated companies did better.'),
    ],
}
